package com.ofaro.participaciones;

import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.os.Bundle;
import android.text.InputType;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;

import org.json.JSONArray;
import org.json.JSONObject;

import java.time.LocalDate;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ReservationsActivity extends Activity {
    private final ExecutorService io=Executors.newSingleThreadExecutor();
    private AppCore core;private LinearLayout page;private TextView subtitle;private String currentMode="HOY";

    @Override protected void onCreate(Bundle b){super.onCreate(b);core=new AppCore(this);setContentView(buildRoot());showList("HOY");}
    @Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}

    private View buildRoot(){LinearLayout root=column();root.setBackgroundColor(Color.rgb(247,246,243));LinearLayout head=column();head.setPadding(dp(18),dp(17),dp(18),dp(14));head.setBackgroundColor(Color.rgb(15,15,15));head.addView(text("O FARO",24,Color.WHITE,true));subtitle=text("Reservas",13,Color.LTGRAY,false);head.addView(subtitle);root.addView(head);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);page=column();page.setPadding(dp(14),dp(15),dp(14),dp(32));scroll.addView(page);root.addView(scroll,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,0,1));return root;}

    private void showList(String mode){currentMode=mode;clear("Reservas");back("Reservas",this::finish);LinearLayout filters=row();for(String m:new String[]{"HOY","PENDIENTES","ACTIVAS","HISTÓRICO"}){Button b=small(m);b.setEnabled(!m.equals(mode));b.setOnClickListener(v->showList(m));filters.addView(b,weight());}page.addView(filters);Button add=primary("+ NUEVA RESERVA");add.setOnClickListener(v->newReservation());page.addView(add,top(dp(10)));
        JSONArray cached=core.cachedArray("reservations_"+mode);TextView status=text(cached.length()>0?"Datos guardados · actualizando…":"Actualizando reservas…",13,Color.GRAY,false);status.setPadding(0,dp(12),0,dp(8));page.addView(status);LinearLayout list=column();page.addView(list);paintList(status,list,mode,cached,countPeople(cached),cached.length()>0);
        if(!core.configured()){status.setText(cached.length()>0?"Servidor sin configurar · datos guardados":"Configura Apps Script en Ajustes");return;}
        io.execute(()->{try{JSONObject req=core.action("reservationList").put("limit",250);if("HOY".equals(mode))req.put("date",LocalDate.now().toString());if("HISTÓRICO".equals(mode))req.put("includeClosed",true);JSONObject r=core.post(req);JSONArray raw=r.optJSONArray("items");if(raw==null)raw=new JSONArray();JSONArray out=filter(raw,mode);core.saveArray("reservations_"+mode,out);int people=countPeople(out);runOnUiThread(()->paintList(status,list,mode,out,people,false));}catch(Exception e){runOnUiThread(()->status.setText(cached.length()>0?"Sin conexión · mostrando datos guardados":"No se pudo cargar · "+msg(e)));}});}

    private JSONArray filter(JSONArray raw,String mode){JSONArray out=new JSONArray();for(int i=0;i<raw.length();i++){JSONObject x=raw.optJSONObject(i);if(x==null)continue;String state=x.optString("state","");String service=x.optString("serviceState","");if("PENDIENTES".equals(mode)&&!"Pendiente".equalsIgnoreCase(state))continue;if("ACTIVAS".equals(mode)){if("Cancelada".equalsIgnoreCase(state)||"Denegada".equalsIgnoreCase(state)||"Completada".equalsIgnoreCase(service)||"No se presentó".equalsIgnoreCase(service))continue;}out.put(x);}return out;}
    private void paintList(TextView status,LinearLayout list,String mode,JSONArray arr,int people,boolean cached){status.setText((cached?"Datos guardados · ":"")+arr.length()+" reservas"+(people>0?" · "+people+" personas":""));list.removeAllViews();if(arr.length()==0){list.addView(infoCard("No hay reservas en este filtro."));return;}for(int i=0;i<arr.length();i++){JSONObject r=arr.optJSONObject(i);if(r!=null)addCard(list,r);}}
    private void addCard(LinearLayout list,JSONObject r){LinearLayout c=card();c.addView(text(r.optString("date","")+" · "+r.optString("time","--:--"),12,Color.GRAY,true));c.addView(text(r.optString("name","Reserva"),20,Color.rgb(20,20,20),true));String meta=r.optInt("people",0)+" personas";if(!r.optString("table","").isEmpty())meta+=" · Mesa "+r.optString("table");if(!r.optString("zone","").isEmpty()&&!"Sin asignar".equalsIgnoreCase(r.optString("zone")))meta+=" · "+r.optString("zone");c.addView(text(meta,14,Color.DKGRAY,false));String state=dash(r.optString("state","Pendiente")),service=dash(r.optString("serviceState","Pendiente"));TextView st=text(state+" · "+service,12,statusColor(state,service),true);st.setPadding(0,dp(6),0,dp(9));c.addView(st);LinearLayout rr=row();Button print=small("TICKET");print.setOnClickListener(v->preview(r));Button manage=small("GESTIONAR");manage.setOnClickListener(v->details(r));rr.addView(print,weight());rr.addView(manage,weight());c.addView(rr);list.addView(c,bottom(dp(9)));}

    private void details(JSONObject r){clear("Reserva");back("Reserva · "+r.optString("name",""),()->showList(currentMode));page.addView(info("Fecha / hora",r.optString("date","")+" · "+r.optString("time","")));page.addView(info("Personas",String.valueOf(r.optInt("people",0))));page.addView(info("Mesa / zona",dash(r.optString("table",""))+" · "+dash(r.optString("zone",""))));page.addView(info("Teléfono",dash(r.optString("phone",""))));page.addView(info("Correo",dash(r.optString("email",""))));page.addView(info("Observaciones",dash(r.optString("notes",""))));page.addView(info("Estado",dash(r.optString("state","Pendiente"))+" · "+dash(r.optString("serviceState","Pendiente"))));Button preview=primary("PREVISUALIZAR / IMPRIMIR");preview.setOnClickListener(v->preview(r));page.addView(preview,top(dp(10)));Button edit=secondary("EDITAR RESERVA COMPLETA");edit.setOnClickListener(v->edit(r));page.addView(edit,top(dp(8)));LinearLayout contact=row();Button call=small("LLAMAR");call.setOnClickListener(v->dial(r.optString("phone","")));Button wa=small("WHATSAPP");wa.setOnClickListener(v->whatsapp(r.optString("phone","")));contact.addView(call,weight());contact.addView(wa,weight());page.addView(contact,topWrap(dp(8)));
        page.addView(label("ESTADO DE RESERVA"));LinearLayout states=row();for(String s:new String[]{"Pendiente","Confirmada","Denegada","Cancelada"}){Button b=small(s.toUpperCase());b.setOnClickListener(v->updateReservation(r,s,null,null,null,null));states.addView(b,weight());}page.addView(states);
        page.addView(label("SERVICIO"));String[] ss={"Pendiente","Llegó","Sentada","En servicio","Completada","No se presentó"};for(int i=0;i<ss.length;i+=2){LinearLayout rr=row();for(int j=i;j<Math.min(i+2,ss.length);j++){String s=ss[j];Button b=small(s.toUpperCase());b.setOnClickListener(v->updateReservation(r,null,s,null,null,null));rr.addView(b,weight());}page.addView(rr,topWrap(dp(7)));}
        page.addView(label("UBICACIÓN RÁPIDA"));LinearLayout loc=row();Button table=small("MESA / ZONA");table.setOnClickListener(v->quickLocation(r));Button notes=small("OBSERVACIONES");notes.setOnClickListener(v->quickNotes(r));loc.addView(table,weight());loc.addView(notes,weight());page.addView(loc);
    }

    private void quickLocation(JSONObject r){LinearLayout box=column();box.setPadding(dp(15),dp(3),dp(15),dp(8));EditText table=field(box,"Mesa",r.optString("table",""),InputType.TYPE_CLASS_TEXT);EditText zone=field(box,"Zona",r.optString("zone","Sin asignar"),InputType.TYPE_CLASS_TEXT);new AlertDialog.Builder(this).setTitle("Mesa y zona").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("GUARDAR",(d,w)->updateReservation(r,null,null,val(table),val(zone),null)).show();}
    private void quickNotes(JSONObject r){EditText notes=input(r.optString("notes",""));notes.setSingleLine(false);notes.setMinLines(4);notes.setGravity(Gravity.TOP);notes.setPadding(dp(12),dp(10),dp(12),dp(10));new AlertDialog.Builder(this).setTitle("Observaciones").setView(notes).setNegativeButton("Cancelar",null).setPositiveButton("GUARDAR",(d,w)->updateReservation(r,null,null,null,null,val(notes))).show();}

    /** Acción estable del backend para estado, servicio, mesa, zona y observaciones. */
    private void updateReservation(JSONObject r,String state,String service,String table,String zone,String notes){io.execute(()->{try{JSONObject q=core.action("reservationUpdate").put("id",r.optString("id",""));if(state!=null)q.put("state",state);if(service!=null)q.put("serviceState",service);if(table!=null)q.put("mesa",table);if(zone!=null)q.put("zona",zone);if(notes!=null)q.put("observaciones",notes);JSONObject x=core.post(q);JSONObject updated=x.optJSONObject("reservation");if(updated==null)updated=x.optJSONObject("item");JSONObject finalUpdated=updated;runOnUiThread(()->{toast("Reserva actualizada");if(finalUpdated!=null)details(finalUpdated);else showList(currentMode);});}catch(Exception e){runOnUiThread(()->alert("No se pudo actualizar",msg(e)));}});}

    private void edit(JSONObject r){clear("Editar");back("Editar reserva",()->details(r));EditText date=field(page,"Fecha · AAAA-MM-DD",r.optString("date",""),InputType.TYPE_CLASS_DATETIME);EditText time=field(page,"Hora · HH:MM",r.optString("time",""),InputType.TYPE_CLASS_DATETIME);EditText name=field(page,"Nombre",r.optString("name",""),InputType.TYPE_CLASS_TEXT);EditText phone=field(page,"Teléfono",r.optString("phone",""),InputType.TYPE_CLASS_PHONE);EditText email=field(page,"Correo",r.optString("email",""),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);EditText people=field(page,"Personas",String.valueOf(r.optInt("people",2)),InputType.TYPE_CLASS_NUMBER);EditText table=field(page,"Mesa",r.optString("table",""),InputType.TYPE_CLASS_TEXT);EditText zone=field(page,"Zona",r.optString("zone","Sin asignar"),InputType.TYPE_CLASS_TEXT);EditText notes=multi(page,"Observaciones",r.optString("notes",""),4);Button save=primary("GUARDAR CAMBIOS");page.addView(save,top(dp(12)));save.setOnClickListener(v->{int p=parse(val(people),2);String error=ReservationRules.validate(val(name),val(phone),val(date),val(time),p);if(!error.isEmpty()){alert("Revisa la reserva",error);return;}save.setEnabled(false);io.execute(()->{try{JSONObject q=core.action("reservationFullUpdate").put("id",r.optString("id","")).put("fecha",val(date)).put("hora",val(time)).put("nombre",val(name)).put("telefono",val(phone)).put("correo",val(email)).put("personas",p).put("mesa",val(table)).put("zona",val(zone)).put("observaciones",val(notes));JSONObject x=core.post(q);JSONObject updated=x.optJSONObject("reservation");runOnUiThread(()->{toast("Reserva guardada");if(updated!=null)details(updated);else showList("HOY");});}catch(Exception e){runOnUiThread(()->{save.setEnabled(true);String m=msg(e);if(m.toLowerCase().contains("acción")||m.toLowerCase().contains("accion"))alert("Backend pendiente de actualizar","La APK ya incluye la edición completa, pero falta publicar el módulo Reservas APK v3 en Apps Script.");else alert("No se pudo guardar",m);});}});});}

    private void newReservation(){clear("Nueva reserva");back("Nueva reserva",()->showList("HOY"));EditText name=field(page,"Nombre","",InputType.TYPE_CLASS_TEXT);EditText phone=field(page,"Teléfono","",InputType.TYPE_CLASS_PHONE);EditText email=field(page,"Correo (opcional)","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS);EditText date=field(page,"Fecha · AAAA-MM-DD",LocalDate.now().toString(),InputType.TYPE_CLASS_DATETIME);EditText time=field(page,"Hora · HH:MM","14:00",InputType.TYPE_CLASS_DATETIME);EditText people=field(page,"Personas","2",InputType.TYPE_CLASS_NUMBER);EditText table=field(page,"Mesa (opcional)","",InputType.TYPE_CLASS_TEXT);EditText zone=field(page,"Zona","Sin asignar",InputType.TYPE_CLASS_TEXT);EditText notes=multi(page,"Observaciones","",4);Button save=primary("GUARDAR Y PREVISUALIZAR");page.addView(save,top(dp(12)));save.setOnClickListener(v->{int p=parse(val(people),2);String error=ReservationRules.validate(val(name),val(phone),val(date),val(time),p);if(!error.isEmpty()){alert("Revisa la reserva",error);return;}save.setEnabled(false);io.execute(()->{try{JSONObject q=core.action("reservationCreate").put("nombre",val(name)).put("telefono",val(phone)).put("correo",val(email)).put("fecha",val(date)).put("hora",val(time)).put("personas",p).put("mesa",val(table)).put("zona",val(zone)).put("observaciones",val(notes));JSONObject x=core.post(q);JSONObject created=x.optJSONObject("reservation");if(created==null)created=new JSONObject().put("id",x.optString("id","")).put("date",val(date)).put("time",val(time)).put("name",val(name)).put("phone",val(phone)).put("email",val(email)).put("people",p).put("table",val(table)).put("zone",val(zone)).put("notes",val(notes)).put("state","Confirmada");JSONObject finalCreated=created;runOnUiThread(()->{save.setEnabled(true);toast("Reserva guardada");preview(finalCreated);});}catch(Exception e){runOnUiThread(()->{save.setEnabled(true);alert("No se pudo guardar",msg(e));});}});});}

    private void preview(JSONObject r){StringBuilder b=new StringBuilder();b.append(r.optString("date","")).append("   ").append(r.optString("time","")).append("\n\n").append(r.optString("name","").toUpperCase()).append("\n").append(r.optInt("people",0)).append(" PERSONAS\n");if(!r.optString("table","").isEmpty())b.append("Mesa: ").append(r.optString("table")).append("\n");if(!r.optString("zone","").isEmpty()&&!"Sin asignar".equalsIgnoreCase(r.optString("zone")))b.append("Zona: ").append(r.optString("zone")).append("\n");if(!r.optString("phone","").isEmpty())b.append("Tel: ").append(r.optString("phone")).append("\n");if(!r.optString("notes","").isEmpty())b.append("\nOBSERVACIONES\n").append(r.optString("notes")).append("\n");b.append("\n").append(r.optString("id",""));Intent i=new Intent(this,TicketPreviewActivity.class);i.putExtra("title","MESÓN O FARO");i.putExtra("subtitle","RESERVA");i.putExtra("body",b.toString());i.putExtra("type","Reserva");i.putExtra("reference",r.optString("id",""));i.putExtra("detail",r.optString("name",""));i.putExtra("reservationId",r.optString("id",""));i.putExtra("template","Reserva Express");startActivity(i);}

    private int countPeople(JSONArray a){int total=0;for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null)total+=x.optInt("people",0);}return total;}
    private int statusColor(String state,String service){if("Cancelada".equalsIgnoreCase(state)||"Denegada".equalsIgnoreCase(state)||"No se presentó".equalsIgnoreCase(service))return Color.rgb(145,60,45);if("Confirmada".equalsIgnoreCase(state)||"Llegó".equalsIgnoreCase(service)||"Sentada".equalsIgnoreCase(service)||"En servicio".equalsIgnoreCase(service))return Color.rgb(30,100,58);return Color.rgb(135,90,30);}
    private void dial(String p){if(p==null||p.trim().isEmpty()){toast("No hay teléfono");return;}startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+p.trim())));}
    private void whatsapp(String p){if(p==null||p.trim().isEmpty()){toast("No hay teléfono");return;}String c=p.replaceAll("[^0-9]","");if(c.length()==9)c="34"+c;try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://wa.me/"+c)));}catch(Exception e){alert("WhatsApp",msg(e));}}

    private void clear(String s){page.removeAllViews();subtitle.setText(s);}private void back(String s,Runnable r){LinearLayout x=row();Button b=secondary("‹ ATRÁS");b.setOnClickListener(v->r.run());x.addView(b,new LinearLayout.LayoutParams(dp(105),dp(48)));TextView t=text(s,20,Color.rgb(20,20,20),true);t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(dp(10),0,0,0);x.addView(t,new LinearLayout.LayoutParams(0,dp(48),1));page.addView(x);}
    private TextView label(String s){TextView t=text(s,12,Color.GRAY,true);t.setPadding(0,dp(17),0,dp(7));return t;}private TextView info(String l,String v){TextView t=text(l.toUpperCase()+"\n"+v,14,Color.rgb(30,30,30),false);t.setPadding(dp(12),dp(10),dp(12),dp(10));t.setBackground(box(Color.WHITE,11,Color.rgb(218,218,218),1));t.setLayoutParams(bottom(dp(7)));return t;}private TextView infoCard(String s){TextView t=text(s,14,Color.DKGRAY,false);t.setPadding(dp(12),dp(12),dp(12),dp(12));t.setBackground(box(Color.WHITE,11,Color.rgb(218,218,218),1));return t;}private LinearLayout card(){LinearLayout c=column();c.setPadding(dp(14),dp(13),dp(14),dp(13));c.setBackground(box(Color.WHITE,14,Color.rgb(218,216,212),1));return c;}
    private LinearLayout column(){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);return c;}private LinearLayout row(){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);r.setGravity(Gravity.CENTER_VERTICAL);return r;}private Button primary(String s){Button b=button(s);b.setTextColor(Color.WHITE);b.setBackground(box(Color.rgb(15,15,15),12,Color.TRANSPARENT,0));return b;}private Button secondary(String s){Button b=button(s);b.setTextColor(Color.rgb(20,20,20));b.setBackground(box(Color.WHITE,12,Color.rgb(190,190,190),1));return b;}private Button small(String s){Button b=secondary(s);b.setTextSize(10);return b;}private Button button(String s){Button b=new Button(this);b.setText(s);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setAllCaps(false);b.setMinHeight(dp(48));return b;}private TextView text(String s,int sp,int c,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(c);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private EditText input(String v){EditText e=new EditText(this);e.setText(v);e.setTextSize(16);e.setTextColor(Color.rgb(20,20,20));e.setPadding(dp(12),0,dp(12),0);e.setBackground(box(Color.WHITE,11,Color.rgb(205,205,205),1));return e;}private EditText field(LinearLayout p,String l,String v,int type){TextView t=text(l,13,Color.DKGRAY,true);t.setPadding(0,dp(8),0,dp(4));p.addView(t);EditText e=input(v);e.setInputType(type);e.setSingleLine(true);p.addView(e,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(50)));return e;}private EditText multi(LinearLayout p,String l,String v,int lines){TextView t=text(l,13,Color.DKGRAY,true);t.setPadding(0,dp(8),0,dp(4));p.addView(t);EditText e=input(v);e.setSingleLine(false);e.setMinLines(lines);e.setGravity(Gravity.TOP);e.setPadding(dp(12),dp(9),dp(12),dp(9));p.addView(e,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));return e;}private GradientDrawable box(int f,int r,int s,int sw){GradientDrawable d=new GradientDrawable();d.setColor(f);d.setCornerRadius(dp(r));if(sw>0)d.setStroke(dp(sw),s);return d;}private LinearLayout.LayoutParams weight(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);p.setMargins(dp(2),0,dp(2),0);return p;}private LinearLayout.LayoutParams top(int v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);p.topMargin=v;return p;}private LinearLayout.LayoutParams topWrap(int v){return top(v);}private LinearLayout.LayoutParams bottom(int v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);p.bottomMargin=v;return p;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private String val(EditText e){return e.getText().toString().trim();}private int parse(String s,int f){try{return Integer.parseInt(s.trim());}catch(Exception e){return f;}}private String dash(String s){return s==null||s.trim().isEmpty()?"—":s.trim();}private String msg(Throwable t){String m=t==null?"Error desconocido":t.getMessage();return m==null||m.trim().isEmpty()?String.valueOf(t):m;}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}private void alert(String t,String m){if(!isFinishing())new AlertDialog.Builder(this).setTitle(t).setMessage(m).setPositiveButton("Aceptar",null).show();}
}
